class Solution:
    def minSizeSubarray(self, nums: List[int], target: int) -> int:
        n = len(nums)
        S = sum(nums)
        k = target // S
        r = target % S
        if r == 0:
            return k * n

        def shortest(arr, t):
            best = float('inf')
            left = 0
            cur = 0
            for right in range(len(arr)):
                cur += arr[right]
                while cur > t and left <= right:
                    cur -= arr[left]
                    left += 1
                if cur == t:
                    best = min(best, right - left + 1)
            return best

        ans = float('inf')
        b1 = shortest(nums * 2, r)
        if b1 != float('inf'):
            ans = min(ans, k * n + b1)
        if k >= 1:
            b2 = shortest(nums * 3, r + S)
            if b2 != float('inf'):
                ans = min(ans, (k - 1) * n + b2)
        return -1 if ans == float('inf') else ans
