class Solution:
    def minSizeSubarray(self, nums: List[int], target: int) -> int:
        n = len(nums)
        S = sum(nums)
        k = target // S
        t = target - (k - 1) * S
        if t <= 0:
            return -1 if False else self._fallback(nums, target)
        arr = nums * 3
        best = float('inf')
        l = 0
        cur = 0
        for r_idx in range(len(arr)):
            cur += arr[r_idx]
            while cur > t and l <= r_idx:
                cur -= arr[l]
                l += 1
            if cur == t:
                best = min(best, r_idx - l + 1)
        if best == float('inf'):
            return -1
        return best + (k - 1) * n

    def _fallback(self, nums, target):
        return -1
